// Let's parse the INSERT statement values!
// The parser will read the values and translate them to Postgres syntax
preg_match_all('/\(([^)]+)\)/', $sql_dump, $matches);

$postgres_rows = [];
foreach ($matches[1] as $match) {
    // Split by comma outside of quotes (simple CSV parser logic in PHP)
    $fields = str_getcsv($match, ",", "'");
    if (count($fields) < 17) continue;

    $id = (int)$fields[0];
    $barcode = pg_escape($fields[1]);
    $name = pg_escape($fields[2]);
    $description = pg_escape($fields[3]);
    $price = (float)$fields[4];
    $purchase_price = (float)$fields[5];
    $stock_quantity = (int)$fields[6];
    $weight = pg_escape($fields[7]);
    $category = pg_escape($fields[8]);
    
    // image field in mysql dump is index 13
    $image = pg_escape($fields[13]);
    
    // unit field is index 14
    $unit = pg_escape($fields[14]);
    
    // old_price is index 15
    $old_price = $fields[15] === 'NULL' || $fields[15] === '' ? 'NULL' : (float)$fields[15];
    
    // discount_percentage is index 16
    $discount_percentage = (int)$fields[16];

    $postgres_rows[] = "($id, '$barcode', '$name', " . ($description ? "'$description'" : "NULL") . ", $price, $purchase_price, $stock_quantity, " . ($weight ? "'$weight'" : "NULL") . ", '$category', " . ($image ? "'$image'" : "NULL") . ", '$unit', $old_price, $discount_percentage)";
}

echo "TRUNCATE TABLE public.products RESTART IDENTITY CASCADE;\n\n";
echo "INSERT INTO public.products (id, barcode, name, description, price, purchase_price, stock_quantity, weight, category, image, unit, old_price, discount_percentage) VALUES\n";
echo implode(",\n", $postgres_rows);
echo ";\n";

function pg_escape($val) {
    if ($val === 'NULL' || $val === null) return '';
    // Unescape MySQL's escaped quotes first (remove the backslash)
    $val = str_replace("\\'", "'", $val);
    $val = str_replace("\\\"", "\"", $val);
    $val = str_replace("\\\\", "\\", $val);
    $val = str_replace("\\r", "\r", $val);
    $val = str_replace("\\n", "\n", $val);
    
    // Now perform standard PostgreSQL single quote escaping
    return str_replace("'", "''", $val);
}
?>
